/* Minimal, permissive React typings for offline typechecking only. */
type SetState<S> = (v: S | ((prev: S) => S)) => void;
export type ReactNode = any;
export type ReactElement = any;
export type CSSProperties = Record<string, string | number | undefined>;
export type FC<P = {}> = (props: P) => any;
export type ComponentType<P = {}> = (props: P) => any;
export type PropsWithChildren<P = {}> = P & { children?: ReactNode };
export type MouseEvent<T = Element> = any;
export type KeyboardEvent<T = Element> = any;
export type ChangeEvent<T = Element> = any;
export type FormEvent<T = Element> = any;
export type PointerEvent<T = Element> = any;
export type RefObject<T> = { current: T };
export type MutableRefObject<T> = { current: T };
export type ButtonHTMLAttributes<T> = Record<string, any>;
export type InputHTMLAttributes<T> = Record<string, any>;
export type AnchorHTMLAttributes<T> = Record<string, any>;
export type HTMLAttributes<T> = Record<string, any>;
export type SVGProps<T> = Record<string, any>;
export type TextareaHTMLAttributes<T> = Record<string, any>;
export type SelectHTMLAttributes<T> = Record<string, any>;
export function useState<S>(init: S | (() => S)): [S, SetState<S>];
export function useState<S = undefined>(): [S | undefined, SetState<S | undefined>];
export function useEffect(f: () => void | (() => void), deps?: readonly unknown[]): void;
export function useLayoutEffect(f: () => void | (() => void), deps?: readonly unknown[]): void;
export function useMemo<T>(f: () => T, deps: readonly unknown[]): T;
export function useCallback<T extends (...a: any[]) => any>(f: T, deps: readonly unknown[]): T;
export function useRef<T>(init: T): MutableRefObject<T>;
export function useRef<T>(init: T | null): RefObject<T | null>;
export function useContext<T>(c: Context<T>): T;
export function useId(): string;
export function useSyncExternalStore<T>(subscribe: (f: () => void) => () => void, get: () => T): T;
export function useReducer<S, A>(r: (s: S, a: A) => S, init: S): [S, (a: A) => void];
export interface Context<T> { Provider: any; Consumer: any }
export function createContext<T>(v: T): Context<T>;
export function memo<T>(c: T): T;
export function forwardRef<T, P = {}>(render: (props: P, ref: any) => any): (props: P & { ref?: any }) => any;
export const Fragment: any;
export const StrictMode: any;
export function lazy(f: () => Promise<any>): any;
export const Suspense: any;
declare const React: any;
export default React;
